def f(g):
    H=len(g);W=len(g[0])
    bg=collections.Counter(v for r in g for v in r).most_common(1)[0][0]
    out=[row[:] for row in g]
    for r in range(H):
        # minority cells within row
        ms=[c for c in range(W) if g[r][c]!=bg]
        if not ms: continue
        bl=[i for i in ms if i==min(ms)]
        # tail = cells after the longest prefix-run of minority
        if bl==ms:  # whole row is minority: tail after len(bl)-1
            for c in range(len(bl),W): out[r][c]=1
        else:
            # find last contiguous block containing min element
            run=[]; started=False
            for c in range(W):
                if g[r][c]==bg and started: break
                if g[r][c]!=bg and not started: started=True
                if g[r][c]!=bg and started: run.append(c)
            if run:
                for c in range(run[-1]+1,W): out[r][c]=1
    return out
