import os,re,json
from collections import Counter

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def runs_of(row,bgv):
    i=0;res=[]
    while i<len(row):
        j=i
        while j<len(row) and row[j]!=bgv: j+=1
        if j>i: res.append((i,j)); i=j+1
        else: i+=1
    return res

def solve(g):
    H,W=len(g),len(g[0])
    bgv=Counter(x for r in g for x in r).most_common(1)[0][0]
    counts={v:sum(r.count(v) for r in g) for v in set(sum(g,[]))}
    other=[v for v in counts if v!=bgv]
    mino=min(other,key=lambda v:counts[v]) if other else None
    out=[row[:] for row in g]
    for r in range(H):
        rs=runs_of(out[r],bgv)
        if not rs: continue
        # last non-bg cell: scan backwards from end for first non-bg
        e=W-1
        while e>=0 and out[r][e]==bgv: e-=1
        if e==-1 or e>=rs[-1][1]: continue
        tail_start=e+1
        seg_touches_left=out[r][0]!=bgv and any(i==0 for i,j in [(s,j) for s,j in []])
        # segment touches left edge?
        seg_starts_zero = any(s==0 for s,_ in rs)
        tail_len = W-tail_start
        mult = seg_starts_zero and tail_len%2==0 and tail_len<= sum(j-i for i,j in runs_of(out[r],bgv) if True) 
        for c in range(tail_start,W):
            if out[r][c]==bgv:
                if mult and (c-tail_start)%2==1:
                    out[r][c]=1
                elif not mult:
                    out[r][c]=1
    return out

for n in range(1,7):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    p=solve(gi)
    print(n, p==go)
    if p!=go:
        for r in range(len(go)):
            if p[r]!=go[r]: print(' ',r,' '.join(map(str,p[r])),'  ',' '.join(map(str,go[r])))

